-- ============================================================================
-- SQL TO UPDATE & STORE PROFILE PICTURE IN MYSQL DATABASE
-- ============================================================================

UPDATE profiles 
SET avatar_url = 'data:image/png;base64,'
WHERE id = (SELECT min_id FROM (SELECT MIN(id) AS min_id FROM profiles) AS t);

-- 1. Check updated columns:
SELECT id, full_name, LEFT(avatar_url, 35) AS image_type, LENGTH(avatar_url) AS total_bytes FROM profiles;

-- 2. Query the picture:
-- (In MySQL Workbench: Right-click this cell -> "Open Value in Viewer" -> "Image" tab)
SELECT avatar_url FROM profiles;
